with cleaned as (select *, concat_ws('-', page, event_type) as page_event_type_key, coalesce(page, 'NONE') as resolved_page from web_events where event_time > timestamp '2023-09-25 08:00:00'), with_gaps as (select *, case when event_time - lag(event_time) over (partition by event_type order by event_time, id) > interval 90 days then 1 else 0 end as session_start_flag from cleaned), sessions_web_events as (select id, session_id, event_type, event_time, page_event_type_key, resolved_page, sum(session_start_flag) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as session_no from with_gaps) select date_trunc('week', event_time) as week_start, date_trunc('quarter', event_time) as quarter_start, min(event_time) as first_seen, percentile_approx(session_no, array(0.25, 0.5, 0.75)) as session_no_quartiles, count(distinct session_id) as distinct_session_ids, min(event_time) as first_event_time, count(distinct event_type) as distinct_event_types, count(case when event_type = 'purchase' then 1 end) as purchase_count from sessions_web_events group by week_start, quarter_start having distinct_session_ids > 1;
